l_amendments/19699/download", "alt_mime_id": 0, "description": "House Judiciary Amendment L.007", "amendment_id": 297025, "alt_amendment": 0, "alt_state_link": "", "amendment_hash": "bd991c1824c6ead9885c42d17b79b507", "amendment_size": 41014, "alt_amendment_hash": "", "alt_amendment_size": 0}, {"url": "https://legiscan.com/CO/amendment/SB015/id/298633", "date": "2026-05-09", "mime": "application/pdf", "title": "Second Reading Amendment L.016", "adopted": 1, "chamber": "", "mime_id": 2, "alt_mime": "", "chamber_id": 0, "state_link": "https://leg.colorado.gov/bill_amendments/20202/download", "alt_mime_id": 0, "description": "Second Reading Amendment L.016", "amendment_id": 298633, "alt_amendment": 0, "alt_state_link": "", "amendment_hash": "aa0da8a7d09241944ed7169589c886e9", "amendment_size": 24675, "alt_amendment_hash": "", "alt_amendment_size": 0}, {"url": "https://legiscan.com/CO/amendment/SB015/id/298634", "date": "2026-05-09", "mime": "application/pdf", "title": "Second Reading Amendment L.015", "adopted": 1, "chamber": "", "mime_id": 2, "alt_mime": "", "chamber_id": 0, "state_link": "https://leg.colorado.gov/bill_amendments/20201/download", "alt_mime_id": 0, "description": "Second Reading Amendment L.015", "amendment_id": 298634, "alt_amendment": 0, "alt_state_link": "", "amendment_hash": "759330d4dc2adcb5e61707c6b9e58e7e", "amendment_size": 34983, "alt_amendment_hash": "", "alt_amendment_size": 0}, {"url": "https://legiscan.com/CO/amendment/SB015/id/298736", "date": "2026-05-11", "mime": "application/pdf", "title": "Third Reading Amendment L.017", "adopted": 1, "chamber": "", "mime_id": 2, "alt_mime": "", "chamber_id": 0, "state_link": "https://leg.colorado.gov/bill_amendments/20251/download", "alt_mime_id": 0, "description": "Third Reading Amendment L.017", "amendment_id": 298736, "alt_amendment": 0, "alt_state_link": "", "amendment_hash": "af1df63d16db9ad02c438285636251df", "amendment_size": 21646, "alt_amendment_hash": "", "alt_amendment_size": 0}], "session_id": 2243, "bill_number": "SB015"}$j$::jsonb] loop
    v_id := (v_bill->>'bill_id')::integer;
    insert into public.civic_genome_family (family_key, family_label, policy_domain)
    values (format('ci-20261122-amendment-base-%s', v_id), format('CI amendment base %s', v_id), 'government')
    returning family_id into v_family;
    insert into public.docket_bill_detail_cache (bill_id, bill, fetched_at, source)
    values (v_id, v_bill, timestamptz '2026-11-22 00:00:00+00', 'legiscan_get_bill_jurisdiction_activation');
    insert into public.civic_genome_bill (family_id, bill_id, state_code, session_key, source_bill_number, source_bill_title,
                                          structural_dna_hash, structural_dna_json)
    select v_family,
      (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-'||substr('89ab',((strpos('0123456789abcdef',substr(h,17,1))-1)%4)+1,1)
        ||substr(h,18,3)||'-'||substr(h,21,12))::uuid,
      v_bill->>'state', v_bill->>'session_id', v_bill->>'bill_number', 'CI real-bill amendment base fixture', repeat('a',64),
      jsonb_build_object('source_bill_id', v_id::text)
    from (select encode(extensions.digest(convert_to('docket_room:legiscan:'||v_id::text,'UTF8'),'sha256'),'hex') h) x;
    perform public.register_docket_legislative_version_spine(v_id, false);
    perform public.register_docket_legislative_version_spine(v_id, true);
  end loop;

  -- Expected bases (null = held). OK: name then date; IN: name; IN draft AM134802 held.
  for v_expect in select * from (values
      ('amendment:2047872:278128','text:2047872:3275336'),
      ('amendment:2047872:293424','text:2047872:3386207'),
      ('amendment:2047872:294000','text:2047872:3386207'),
      ('amendment:2047872:297107','text:2047872:3419043'),
      ('amendment:2065791:267567',null),
      ('amendment:2065791:267722','text:2065791:3300219'),
      ('amendment:2065791:268508','text:2065791:3328957'),
      ('amendment:2065791:271335','text:2065791:3333898'),
      ('amendment:2065791:276379','text:2065791:3365376'),
      ('amendment:2065791:276812','text:2065791:3365376')) e(k, base) loop
    if (select d.base_source_document_key from public.docket_bill_source_document d where d.source_document_key = v_expect.k)
       is distinct from v_expect.base then
      raise exception 'amendment_base_mismatch % expected % got %', v_expect.k, v_expect.base,
        (select d.base_source_document_key from public.docket_bill_source_document d where d.source_document_key = v_expect.k);
    end if;
  end loop;

  -- No attached base is dated after its amendment.
  select count(*) into v_n
  from public.docket_bill_source_document a join public.docket_bill_source_document b on b.source_document_key = a.base_source_document_key
  where a.source_bill_id in (2047872, 2065791, 2079671) and a.provider_date >= date '1990-01-01'
    and b.provider_date >= date '1990-01-01' and b.provider_date > a.provider_date;
  if v_n <> 0 then raise exception 'amendment_base_dated_after_amendment count=%', v_n; end if;

  -- Colorado: every file is named "download"; no name evidence, so nothing attaches.
  select count(*) into v_n from public.docket_bill_source_document
  where source_bill_id = 2079671 and document_family = 'amendment' and base_source_document_key is not null;
  if v_n <> 0 then raise exception 'colorado_download_name_attached count=%', v_n; end if;

  -- Contested path (Option A): give Colorado's amendments the old rule's base, then re-register.
  update public.docket_bill_source_document set base_source_document_key = 'text:2079671:3445859', updated_at = now()
  where source_bill_id = 2079671 and document_family = 'amendment';
  perform public.register_docket_legislative_version_spine(2079671, true);
  select count(*) into v_n from public.docket_amendment_base_receipt
  where source_document_key like 'amendment:2079671:%' and status = 'contested_existing_base';
  if v_n <> 7 then raise exception 'contested_receipts expected 7 got %', v_n; end if;
  select count(*) into v_n from public.civic_genome_legislative_version_queue q
  join public.civic_genome_bill_version v using (bill_version_id)
  where v.source_bill_id = 2079671 and v.document_family = 'amendment' and q.queue_state = 'eligible';
  if v_n <> 0 then raise exception 'contested_amendments_queued count=%', v_n; end if;

  -- Re-running changes nothing: no new receipts, same bases.
  select count(*) into v_receipts from public.docket_amendment_base_receipt;
  perform public.register_docket_legislative_version_spine(id, true) from unnest(array[2047872, 2065791, 2079671]) id;
  if (select count(*) from public.docket_amendment_base_receipt) <> v_receipts then
    raise exception 'amendment_base_rerun_not_idempotent';
  end if;

  -- Receipts are append-only.
  begin
    update public.docket_amendment_base_receipt set reason = 'tamper' where receipt_id = (select min(receipt_id) from public.docket_amendment_base_receipt);
    raise exception 'amendment_base_receipt_update_not_refused';
  exception when insufficient_privilege then null;
  end;

  raise notice 'docket_amendment_base_evidence_v1 real-bill acceptance passed (OK SB206, IN HB1348, CO SB015)';
end
$acceptance$;
rollback;
